package com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.service;

import java.util.List;import java.util.Map;
import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import com.alels.backend.serverops.shared.security.JwtUserContext;import com.alels.backend.telemetry.device.repository.TelemetryDeviceRepository;import com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.dto.DeviceWorkspaceDataSourceDtos.*;import com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.repository.DeviceWorkspaceDataSourceRepository;import com.fasterxml.jackson.databind.ObjectMapper;

@Service
public class DeviceWorkspaceDataSourceService{
 private final DeviceWorkspaceDataSourceRepository repository;private final TelemetryDeviceRepository devices;private final ObjectMapper mapper;
 public DeviceWorkspaceDataSourceService(DeviceWorkspaceDataSourceRepository repository,TelemetryDeviceRepository devices,ObjectMapper mapper){this.repository=repository;this.devices=devices;this.mapper=mapper;}
 public List<SourceOption> options(JwtUserContext user,Long deviceId){var d=device(user,deviceId);return repository.options(d.imei());}
 public ProfileList profiles(JwtUserContext user,Long deviceId){device(user,deviceId);return new ProfileList(repository.profiles(user.companyId()),repository.effectiveId(user.companyId(),deviceId));}
 @Transactional public Profile save(JwtUserContext user,Long deviceId,SaveProfileRequest request){device(user,deviceId);if(request==null)throw bad("Configuration is required.");String name=text(request.name(),120,"Configuration name");String workspace=jsonObject(request.workspaceConfiguration());String units=json(request.unitPreferences()==null?Map.of():request.unitPreferences());Long id=repository.upsert(user.companyId(),user.userId(),name,source(request.rpmSource()),sourceOr(request.speedSource(),"__gps_speed__"),source(request.levelSource()),source(request.consumptionSource()),source(request.odometerSource()),workspace,units);applyTargets(user,deviceId,id,request.deviceIds(),Boolean.TRUE.equals(request.applyAll()));return repository.profile(user.companyId(),id).orElseThrow();}
 @Transactional public Profile apply(JwtUserContext user,Long deviceId,ApplyProfileRequest request){device(user,deviceId);if(request==null||request.profileId()==null||request.profileId()<=0)throw bad("Profile is required.");Profile p=repository.profile(user.companyId(),request.profileId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile was not found in your company."));applyTargets(user,deviceId,p.id(),request.deviceIds(),Boolean.TRUE.equals(request.applyAll()));return repository.profile(user.companyId(),p.id()).orElse(p);}
 @Transactional public void delete(JwtUserContext user,Long deviceId,Long profileId){device(user,deviceId);if(profileId==null||profileId<=0)throw bad("Profile is required.");repository.profile(user.companyId(),profileId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile was not found in your company."));if(!repository.deleteProfile(user.companyId(),profileId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile was not found in your company.");}
 private void applyTargets(JwtUserContext user,Long current,Long profile,List<Long> ids,boolean all){if(all){repository.applyAll(user.companyId(),profile);return;}List<Long> targets=ids==null||ids.isEmpty()?List.of(current):ids.stream().distinct().toList();for(Long id:targets){if(id==null||!repository.deviceInCompany(user.companyId(),id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"One or more selected devices are outside your company.");repository.applyDevice(user.companyId(),id,profile,user.userId());}}
 private TelemetryDeviceRepository.DeviceAccess device(JwtUserContext user,Long id){if(user==null||user.companyId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Company context is required.");var d=devices.accessById(id,user.companyId(),user.normalizedRole()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Device not found or outside your scope."));if(!d.companyId().equals(user.companyId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Configuration profiles are isolated to your company.");return d;}
 private String jsonObject(String value){String v=value==null||value.isBlank()?"{\"instruments\":[],\"bottomItems\":[]}":value;try{if(!mapper.readTree(v).isObject())throw bad("Workspace configuration must be a JSON object.");return v;}catch(ResponseStatusException e){throw e;}catch(Exception e){throw bad("Workspace configuration is invalid.");}}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw bad("Unit preferences are invalid.");}}
 private static String source(String v){return v==null?"":v.trim();}private static String sourceOr(String v,String d){String s=source(v);return s.isBlank()?d:s;}private static String text(String v,int max,String label){String s=v==null?"":v.trim();if(s.isBlank())throw bad(label+" is required.");if(s.length()>max)throw bad(label+" is too long.");return s;}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
